export function rollDice(notation){const match=/^(\d{1,2})d(\d{1,4})([+-]\d{1,4})?$/.exec(notation.trim());if(!match)throw Error('Use 1d20, 2d6 or 1d20+3');const count=+match[1],sides=+match[2],modifier=+(match[3]||0);if(count<1||count>50||sides<2||sides>1000)throw Error('Dice limits: 1–50 dice, 2–1000 sides');const rolls=Array.from({length:count},()=>{const b=new Uint32Array(1),limit=Math.floor(4294967296/sides)*sides;do{crypto.getRandomValues(b);}while(b[0]>=limit);return b[0]%sides+1;});return {rolls,modifier,total:rolls.reduce((a,b)=>a+b,modifier)};}
export function validateEncounterProposal(value,inventory){const layout=reviewedLayout(value,inventory.map(x=>x.id)),p=defaults();p.name=layout.name;p.items=layout.items;validateProject(p);for(const i of p.items){const s=connectionSpec(i.type),swap=i.rotation%180!==0,w=(swap?s.depth:s.width)/25.4,d=(swap?s.width:s.depth)/25.4;if(Math.abs(i.x)+w/2>12||Math.abs(i.z)+d/2>12)throw Error('A piece footprint extends beyond the encounter board');}const report=connectionReport(p);let collision=false;for(let i=0;i<p.items.length;i++)for(let j=i+1;j<p.items.length;j++){const a=p.items[i],b=p.items[j];if(Math.abs(a.y-b.y)<7.99&&footprintsOverlap(a,connectionSpec(a.type),b,connectionSpec(b.type)))collision=true;}if(collision)throw Error('Proposal contains overlapping pieces. Ask for a revised layout.');return {project:p,report};}
