 const toolbar=document.createElement('button');toolbar.id='campaign-home';toolbar.textContent='Campaigns';toolbar.onclick=()=>showHome();document.querySelector('.header-actions').append(toolbar);const settingsButton=document.createElement('button');settingsButton.id='campaign-settings-global';settingsButton.className='studio-global-settings';settingsButton.title='AI and application settings';settingsButton.setAttribute('aria-label','Settings');settingsButton.textContent='⚙';document.querySelector('.header-actions').append(settingsButton);
