 activity.onclick=run(async()=>{const entries=await api.campaignAgentHistory(campaign.id),documents=await api.campaignWorkspaceDocuments(campaign.id),dialog=document.createElement('dialog');dialog.className='studio-dialog';dialog.innerHTML='<h2>Workspace agent activity</h2><div class="agent-history"></div><h3>Campaign documents</h3><div class="agent-documents"></div><button class="primary">Undo last agent action</button><button>Close</button>';for(const entry of entries){const p=document.createElement('p');p.textContent=entry.at+' · '+entry.action+(entry.path?' · '+entry.path:'');dialog.querySelector('.agent-history').append(p);}for(const doc of documents){const button=document.createElement('button');button.textContent=doc.path;button.onclick=async()=>{const data=await api.campaignWorkspaceDocument(campaign.id,doc.path);const pre=document.createElement('pre');pre.textContent=data.content;dialog.querySelector('.agent-documents').replaceChildren(pre);};dialog.querySelector('.agent-documents').append(button);}const buttons=dialog.querySelectorAll(':scope > button');buttons[0].disabled=!entries.length;buttons[0].onclick=async()=>{try{const undone=await api.campaignAgentUndo(campaign.id);campaign=undone.campaign;if(undone.project)replace(validateProject(undone.project));render();dialog.close();status('Last agent action undone.');}catch(e){toast(e.message,true);}};buttons[1].onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();document.body.append(dialog);dialog.showModal();});
 async function showHome(){if(busy)return;await saveQueue;$('studio-route').replaceChildren();$('studio-route').hidden=true;if(!home.open)home.showModal();await refreshHome();}
 function run(fn){return async event=>{event?.preventDefault();if(editing){toast('Please wait for the current action to finish',true);return;}editing=true;$('campaign-fields').disabled=true;$('campaign-chat-fields').disabled=true;try{await fn(event);}catch(e){status(e.message,true);toast(e.message,true);}finally{editing=false;$('campaign-fields').disabled=busy;$('campaign-chat-fields').disabled=busy;}};}
 $('studio-home-close').onclick=()=>home.close();$('campaign-close').onclick=()=>{if(!busy)panel.close();};panel.addEventListener('cancel',e=>{if(busy)e.preventDefault();});$('campaign-cancel-ai').onclick=()=>api.campaignAICancel();
 async function refreshHome(){try{const [campaigns,worlds,scenes]=await Promise.all([api.campaignList(),api.projectList?.('world')||[],api.projectList?.('scene')||[]]);workspaceEntries={campaign:campaigns||[],world:worlds||[],scene:scenes||[]};for(const kind of ['campaign','world','scene'])paintRecent(kind);}catch(e){for(const kind of ['campaign','world','scene']){$('studio-recent-'+kind).textContent='Saved files could not be loaded: '+e.message;}}}
 function paintRecent(kind){const target=$('studio-recent-'+kind),entries=workspaceEntries[kind]||[],showAll=!!allLists[kind];target.replaceChildren();const shown=showAll?entries:entries.slice(0,5);if(!shown.length){const empty=document.createElement('p');empty.className='studio-empty-list';empty.textContent=kind==='campaign'?'No campaign workspaces saved yet.':'No saved '+(kind==='world'?'worlds':'encounters or scenes')+' yet.';target.append(empty);}for(const entry of shown){const row=document.createElement('button');row.className='studio-file-row';const copy=document.createElement('span'),name=document.createElement('strong'),meta=document.createElement('small'),arrow=document.createElement('span');name.textContent=(kind==='campaign'?'Continue ':'Open ')+entry.name;meta.textContent=kind==='campaign'?'Revision '+entry.revision+' · '+new Date(entry.modified).toLocaleDateString():new Date(entry.modified).toLocaleDateString()+' · '+(entry.file||'Scene library');arrow.textContent='›';copy.append(name,meta);row.append(copy,arrow);row.onclick=run(()=>kind==='campaign'?openCampaign(entry.id):openProjectEntry(entry,kind));target.append(row);}const more=home.querySelector(`[data-show-all="${kind}"]`);more.hidden=entries.length<=5;if(entries.length>5)more.textContent=showAll?'Show recent five':'Show all '+(kind==='scene'?'encounters':'')+' ('+entries.length+')';}
 async function openProjectEntry(entry,kind){if(isDirty()&&!confirm('Save the current project first if needed. Open '+entry.name+'?'))return;if(openSavedProject&&!entry.library){if(await openSavedProject(entry.file,kind))home.close();return;}const opened=entry.library?await api.sceneLibraryLoad(entry.id):await api.projectLoad(entry.file,kind);if(opened){replace(validateProject(JSON.parse(opened.data)));home.close();}}
