 function totalLine(t){if(!t.requests)return 'No requests yet';return number(t.inputTokens)+' input · '+number(t.outputTokens)+' output tokens · '+(t.unavailableCosts?money(t.knownCostUsd)+' known portion + '+t.unavailableCosts+' unavailable':money(t.knownCostUsd));}
 function renderUsage(u){if(!u)return;const last=u.last,lastText=last?last.provider+' · '+last.model+' · '+last.kind+' · '+(last.usage?number(last.usage.inputTokens)+' input / '+number(last.usage.outputTokens)+' output tokens':'Usage not reported')+' · '+money(last.cost.nanoUsd===null?null:last.cost.nanoUsd/1e9):'No requests yet';const common='<h3>Usage on this computer</h3><p><strong>Last request</strong><br>'+escape(lastText)+'</p><div class="campaign-usage-totals"><div><strong>This app session · text</strong><p>'+escape(totalLine(u.session.text))+'</p></div><div><strong>All time · text</strong><p>'+escape(totalLine(u.allTime.text))+'</p></div></div><details><summary>Images, cached tokens &amp; pricing details</summary><p>Images this session: '+escape(totalLine(u.session.image))+'</p><p>Images all time: '+escape(totalLine(u.allTime.image))+'</p><p>All-time text cache reads: '+number(u.allTime.text.cacheReadTokens)+' · cache creation: '+number(u.allTime.text.cacheCreationTokens)+'</p><p>'+escape(last?.cost.reason||'Prices use reported token counts. Reasoning is included in output, never added twice.')+'</p><p>'+escape(u.pricingWarning||('Rates checked '+(u.priceTable?.verifiedOn||'unavailable')+' · '+(u.priceTable?.version||'unavailable')))+'</p><p>Totals since '+escape(u.since)+' · recent '+u.retainedRequests+' request records retained.</p></details>';$('campaign-ai-spending').innerHTML=common;$('campaign-usage').textContent=last?'Last request: '+money(last.cost.nanoUsd===null?null:last.cost.nanoUsd/1e9)+' · '+(last.usage?(last.usage.inputTokens===null||last.usage.outputTokens===null?'partial token counts':number(last.usage.inputTokens+last.usage.outputTokens)+' reported tokens'):'usage unavailable'):'';}
